<?php get_header(); while(have_posts()): the_post(); ?><article <?php post_class('single-shell'); ?>><header class="page-heading"><p class="eyebrow"><?php echo esc_html(get_the_date()); ?> / <?php the_author(); ?></p><h1><?php the_title(); ?></h1></header><?php if(has_post_thumbnail()) the_post_thumbnail('full',array('class'=>'article-cover')); ?><div class="prose entry-content"><?php the_content(); wp_link_pages(); ?></div><?php the_post_navigation(); if(comments_open() || get_comments_number()) comments_template(); ?></article><?php endwhile; get_footer(); ?>